using FleetConsole.Domain.Common;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace FleetConsole.Infrastructure.Persistence.Configurations;

/// <summary>Mapping shared by every aggregate root: domain-assigned key and the <c>xmin</c> concurrency token.</summary>
internal static class AggregateRootMapping
{
    /// <summary>
    /// Maps the aggregate to <paramref name="table"/>, keys it by <see cref="Entity{TId}.Id"/> (assigned by the Domain,
    /// never generated by the database) and maps <see cref="AggregateRoot{TId}.Version"/> to PostgreSQL's <c>xmin</c>
    /// system column. <c>xmin</c> changes on every write, so EF Core's <c>WHERE xmin = @original</c> on updates and
    /// deletes detects a concurrent change (ADR-0013 §4); it is not a real column and needs no migration.
    /// </summary>
    /// <typeparam name="TAggregate">The aggregate type.</typeparam>
    /// <typeparam name="TId">Its strongly typed id (converted by convention).</typeparam>
    /// <param name="builder">The entity builder.</param>
    /// <param name="table">The snake_case table name.</param>
    public static void MapAggregateRoot<TAggregate, TId>(this EntityTypeBuilder<TAggregate> builder, string table)
        where TAggregate : AggregateRoot<TId>
        where TId : notnull
    {
        builder.ToTable(table);
        builder.HasKey(aggregate => aggregate.Id);
        builder.Property(aggregate => aggregate.Id).ValueGeneratedNever();
        builder.Property(aggregate => aggregate.Version).IsRowVersion();
    }
}
